/* Player-installed HD texture packs (FORK-053): the setting, when to look for
 * a pack, and lookups for the renderer. See hd_textures.h. */
#include "hd_textures.h"

#include <algorithm>
#include <atomic>
#include <cstdio>
#include <cstdlib>
#include <set>
#include <string>
#include <system_error>

#include "port_hd_download.h"
#include "port_hd_textures.h"

extern "C" {
/* Generated by port/fast3d/hd_texture_scope_embed.cmake from port/fast3d/texture_packs. */
extern const unsigned char hd_level_sources_json[];
extern const size_t hd_level_sources_json_size;
extern const unsigned char hd_level_native_aliases_json[];
extern const size_t hd_level_native_aliases_json_size;
extern const unsigned char hd_dam_native_aliases_json[];
extern const size_t hd_dam_native_aliases_json_size;
}

namespace {
constexpr unsigned kCheckFrames = 300;  /* look for an added or removed pack about every 5 s */

std::atomic<int> g_requested{1};
std::atomic<int> g_found{-1};           /* keys found by the last search; -1 before one */
std::string g_root;
int g_current = -1;
unsigned g_frames = 0;
std::string g_signature;
hd_textures::Pack g_pack;
std::set<hd_textures::Key> g_reported;

std::string text(const unsigned char *data, size_t size) {
    return std::string(reinterpret_cast<const char *>(data), size);
}

/* The HUD ammo icons' art in the pack, by slot: the visible size of the
 * game's icon and the pack key of its image (from the pack's UI/Ammo folder;
 * the tank shell's six palette copies are one image). */
struct AmmoArt {
    unsigned width, height;
    hd_textures::Key key;
};
const AmmoArt kAmmo[hd_textures::kAmmoSlots] = {
    {5, 12, {0xAF0A1953, 0, 0, 3}},   /* 9 mm */
    {5, 28, {0xAC193F4F, 0, 0, 3}},   /* rifle */
    {6, 20, {0x2B351868, 0, 0, 3}},   /* shotgun */
    {6, 24, {0x98685E98, 0, 0, 3}},   /* throwing knife */
    {8, 21, {0xEC11BEAB, 0, 0, 3}},   /* grenade launcher */
    {7, 22, {0xBA97A223, 0, 0, 3}},   /* rocket */
    {0, 0, {0, 0, 0, 0}},             /* plain mine: no HD art */
    {14, 18, {0xAF8E57EF, 0, 0, 3}},  /* grenade */
    {5, 15, {0x91651507, 0, 0, 3}},   /* magnum */
    {5, 12, {0xFA82F840, 0, 0, 3}},   /* golden gun */
    {14, 14, {0x551F375D, 0, 0, 3}},  /* remote mine */
    {14, 14, {0x6F1AC5BE, 0, 0, 3}},  /* timed mine */
    {14, 14, {0x8640BBB3, 0, 0, 3}},  /* proximity mine */
    {7, 22, {0x0590F622, 0, 2, 1}},   /* tank shell */
};

const hd_textures::Scope &scope() {
    static hd_textures::Scope s;
    static bool loaded = false;
    if (!loaded) {
        loaded = true;
        if (!hd_textures::parse_scope(text(hd_level_sources_json, hd_level_sources_json_size),
                                      {text(hd_level_native_aliases_json, hd_level_native_aliases_json_size),
                                       text(hd_dam_native_aliases_json, hd_dam_native_aliases_json_size)},
                                      s)) {
            std::fprintf(stderr, "hd: the texture scope could not be read; original textures stay\n");
        }
        for (const AmmoArt &art : kAmmo) {
            if (art.width) s.keys.insert(art.key);  /* indexed, found by slot rather than by tile */
        }
    }
    return s;
}

/* What is directly in the pack folder (names, sizes, times), to notice a pack
 * being added, replaced or removed without rescanning every file. */
std::string signature() {
    std::string out;
    std::error_code error;
    for (auto it = std::filesystem::directory_iterator(g_root, error);
         !error && it != std::filesystem::directory_iterator(); it.increment(error)) {
        std::error_code e;
        out += it->path().filename().string();
        out += '|';
        if (it->is_regular_file(e)) out += std::to_string(it->file_size(e));
        out += '|';
        out += std::to_string(it->last_write_time(e).time_since_epoch().count());
        out += '\n';
    }
    return out;
}
}  // namespace

extern "C" void portTexturePackRoot(const char *root) { g_root = root ? root : ""; }
extern "C" void portTexturePackSet(int mode) { g_requested.store(mode ? 1 : 0); }
extern "C" int portTexturePackGet(void) { return g_requested.load(); }
extern "C" const char *portTexturePackValueText(const char *text) {
    if (g_found.load() != 0) return text;
    return portHdTexturesState() == PORT_HDTEX_UNSUPPORTED ? "HD (not found)\n" : "HD (Get)\n";
}

namespace hd_textures {
bool beginFrame() {
    const int mode = g_requested.load();
    const bool changed = mode != g_current;
    if (!changed && (!mode || ++g_frames % kCheckFrames != 0)) return false;
    std::string now = mode && !g_root.empty() ? signature() : std::string();
    if (!changed && now == g_signature) return false;
    g_current = mode;
    g_signature = now;
    g_pack.clear();
    g_reported.clear();
    if (mode && !g_root.empty()) {
        const size_t found = g_pack.index(std::filesystem::path(g_root), scope());
        g_found.store(int(found));
        if (found) std::fprintf(stderr, "hd: %zu environment textures from the pack in %s\n", found, g_root.c_str());
        else std::fprintf(stderr, "hd: no HD texture pack in %s; original textures stay\n", g_root.c_str());
        std::fflush(stderr);
    }
    return true;
}

bool ammo_available(int slot) {
    return g_current && slot >= 0 && slot < kAmmoSlots && kAmmo[slot].width && g_pack.find(kAmmo[slot].key);
}

bool ammo_icon(int slot, unsigned tile_width, unsigned tile_height, Image &image) {
    if (!ammo_available(slot)) return false;
    const AmmoArt &art = kAmmo[slot];
    if (tile_width < art.width || tile_height < art.height || tile_width > 64 || tile_height > 64) return false;
    Image source;
    if (!Pack::read(*g_pack.find(art.key), source)) return false;
    const Image sized = resample(source, art.width * kAmmoScale, art.height * kAmmoScale);
    if (sized.rgba.empty()) return false;
    image.width = tile_width * kAmmoScale;
    image.height = tile_height * kAmmoScale;
    image.rgba.assign(size_t(image.width) * image.height * 4, 0);
    for (unsigned y = 0; y < sized.height; y++) {
        std::copy(sized.rgba.begin() + size_t(y) * sized.width * 4, sized.rgba.begin() + size_t(y + 1) * sized.width * 4,
                  image.rgba.begin() + size_t(y) * image.width * 4);
    }
    return true;
}

bool lookup(const Tile &tile, Image &image) {
    if (!g_current || !g_pack.size()) return false;
    Key key;
    if (!identify(tile, key)) return false;
    const Entry *entry = g_pack.find(key);
    if (entry == nullptr) {
        if (std::getenv("GE_HD_TRACE") && g_reported.insert(key).second) {
            std::fprintf(stderr, "hd: miss %08X#%u#%u#%08X native=%ux%u\n", key.texture, key.format, key.size,
                         key.palette, tile.width, tile.height);
        }
        return false;
    }
    /* Same shape, at least the native size: anything else keeps the original. */
    if (!Pack::read(*entry, image) || uint64_t(image.width) * tile.height != uint64_t(image.height) * tile.width
        || image.width < tile.width) {
        if (g_reported.insert(key).second) {
            std::fprintf(stderr, "hd: unusable image for %08X in %s; original kept\n", key.texture,
                         entry->file.string().c_str());
        }
        image = Image{};
        return false;
    }
    if (std::getenv("GE_HD_TRACE") && g_reported.insert(key).second) {
        std::fprintf(stderr, "hd: match %08X#%u#%u#%08X %ux%u -> %ux%u\n", key.texture, key.format, key.size,
                     key.palette, tile.width, tile.height, image.width, image.height);
    }
    return true;
}
}  // namespace hd_textures
